const MovieCard = ({ movie }) => {
  return (
    <div className="movie-card max-w-sm bg-white rounded-lg shadow-md overflow-hidden m-4 cursor-pointer">
      <img className="w-full h-64 object-cover" src={movie.posterUrl} alt={movie.title} />
      <div className="p-4">
        <h3 className="text-lg font-semibold">{movie.title}</h3>
      </div>
    </div>
  );
};

export default MovieCard;
